bg=9
out=[[bg]*13 for _ in range(13)]
# place panels at top-left (1,1), (1,7), (7,1),(7,7); each panel 5x5
panels=[(1,1,8,{(0,0),(0,2),(1,0),(2,1)}),
        (1,7,3,{(0,0),(0,2),(1,0),(1,2)}),
        (7,1,1,{(0,0),(0,2),(2,1)}),
        (7,7,7,{(0,1),(0,2),(1,0),(2,0)})]
for r0,c0,col,holes in panels:
    for dr in range(5):
        for dc in range(5):
            if dr in (0,4) or dc in (0,4):
                out[r0+dr][c0+dc]=col
            elif (dr-1,dc-1) in holes:
                out[r0+dr][c0+dc]=col
print('\n'.join(' '.join(map(str,row)) for row in out))
